53	     * telephone and last name, de-duplicated against already-stored owners. Call this after
54	     * the telephone has been normalized and before the owner is saved.
55	     *
56	     * @param owner the owner being created
57	     */
58	    public void assign(Owner owner) {
59	        String base = owner.getRegion() + "-"
60	            + Sha256Hex.prefix(owner.getTelephone() + owner.getLastName(), HASH_LENGTH);
61	        owner.setCustomerCode(deduplicate(base));
62	    }
