64	    private String deduplicate(String base) {
65	        Set<String> existing = clinicService.findAllOwners().stream()
66	            .map(Owner::getCustomerCode)
67	            .collect(Collectors.toSet());
68	        if (!existing.contains(base)) {
69	            return base;
70	        }
71	        int n = 2;
72	        while (existing.contains(base + "-" + n)) {
73	            n++;
74	        }
75	        return base + "-" + n;
76	    }
